package com.hrx.recovery;
import java.util.*;import java.security.*;import java.security.interfaces.RSAPublicKey;import java.nio.file.*;import java.net.*;import java.net.http.*;import java.time.Instant;
import com.fasterxml.jackson.databind.ObjectMapper;import com.nimbusds.jose.*;import com.nimbusds.jose.crypto.RSASSASigner;import com.nimbusds.jose.jwk.*;import com.nimbusds.jwt.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.test.context.DynamicPropertyRegistry;
final class TestSupport {
 static final ObjectMapper JSON=new ObjectMapper();static final KeyPair KEY=key();static final com.sun.net.httpserver.HttpServer ISSUER=issuer();static final String ISS="http://127.0.0.1:"+ISSUER.getAddress().getPort();
 static final UUID PROJECT=UUID.fromString("20000000-0000-0000-0000-000000000001"),OTHER=UUID.fromString("20000000-0000-0000-0000-000000000002");
 static KeyPair key(){try{var g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);return g.generateKeyPair();}catch(Exception e){throw new IllegalStateException(e);}}
 static com.sun.net.httpserver.HttpServer issuer(){try{var s=com.sun.net.httpserver.HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);s.createContext("/",e->{String body=e.getRequestURI().getPath().equals("/jwks")?new JWKSet(new RSAKey.Builder((RSAPublicKey)KEY.getPublic()).keyID("TEST-recovery").build()).toString():"{\"issuer\":\"http://127.0.0.1:"+s.getAddress().getPort()+"\",\"jwks_uri\":\"http://127.0.0.1:"+s.getAddress().getPort()+"/jwks\"}";byte[] b=body.getBytes(java.nio.charset.StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(200,b.length);try(var out=e.getResponseBody()){out.write(b);}});s.start();Runtime.getRuntime().addShutdownHook(new Thread(()->s.stop(0)));return s;}catch(Exception e){throw new IllegalStateException(e);}}
 static void properties(DynamicPropertyRegistry r){String url=System.getenv("HRX_TEST_DB_URL");if(url==null||!url.matches("jdbc:postgresql:.*[/]hrx_test_[A-Za-z0-9_]+"))throw new IllegalStateException("Use an explicitly isolated hrx_test_ database");
  r.add("spring.datasource.url",()->url);r.add("spring.datasource.username",()->"hrx_recovery_app");r.add("spring.datasource.password",()->System.getenv().getOrDefault("HRX_TEST_APP_PASSWORD",""));r.add("spring.flyway.enabled",()->true);r.add("spring.flyway.user",()->"hrx_recovery_migrator");r.add("spring.flyway.password",()->System.getenv().getOrDefault("HRX_TEST_MIGRATOR_PASSWORD",""));r.add("spring.security.oauth2.resourceserver.jwt.issuer-uri",()->ISS);r.add("spring.security.oauth2.resourceserver.jwt.audiences",()->"hrx-api");
 }
 static UUID user(int n){return UUID.fromString("10000000-0000-0000-0000-"+String.format("%012d",n));}
 static JdbcTemplate admin(){return new JdbcTemplate(new DriverManagerDataSource(System.getenv("HRX_TEST_DB_URL"),System.getenv().getOrDefault("HRX_TEST_ADMIN_USER",System.getProperty("user.name")),System.getenv().getOrDefault("HRX_TEST_ADMIN_PASSWORD","")));}
 static void fixtures(){var j=admin();for(int n=1;n<=6;n++)j.update("INSERT INTO hrx.user_account(user_id,idp_subject,display_name,org_unit_code,job_title,active) VALUES (?,?,?,'TEST-ORG','TEST role',true) ON CONFLICT DO NOTHING",user(n),"TEST-"+n,"TEST employee "+n);for(UUID id:List.of(PROJECT,OTHER))j.update("INSERT INTO hrx.business_project(project_id,project_code,project_name,org_unit_code) VALUES (?,?,?,'TEST-ORG') ON CONFLICT DO NOTHING",id,id.equals(PROJECT)?"TEST-A":"TEST-B","TEST isolated project");
  for(int n=1;n<=4;n++){for(String a:List.of("read","create","update","approve","receive","inspect","read_price"))grant(j,n,"supply_chain",a);for(String a:List.of("read","create"))grant(j,n,"controlled_file",a);}grant(j,6,"supply_chain","read");
 }
 static void grant(JdbcTemplate j,int n,String resource,String action){j.update("INSERT INTO hrx.capability_grant(user_id,project_id,resource_type,action_code,enabled,approved_by,approved_at) SELECT ?,?,?,?,true,?,now() WHERE NOT EXISTS(SELECT 1 FROM hrx.capability_grant WHERE user_id=? AND project_id=? AND resource_type=? AND action_code=?)",user(n),PROJECT,resource,action,user(5),user(n),PROJECT,resource,action);}
 static String token(int n) throws Exception{return token(n,"hrx-api",Instant.now().plusSeconds(900),ISS);}
 static String token(int n,String audience,Instant expiry,String issuer) throws Exception{var claims=new JWTClaimsSet.Builder().subject("TEST-"+n).issuer(issuer).audience(audience).issueTime(Date.from(Instant.now().minusSeconds(600))).expirationTime(Date.from(expiry)).build();var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).keyID("TEST-recovery").build(),claims);jwt.sign(new RSASSASigner(KEY.getPrivate()));return jwt.serialize();}
 static java.time.LocalDate today(){return java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"));}
 static Map<String,Object> demand(){return Map.of("projectId",PROJECT.toString(),"bomLine","TEST-"+UUID.randomUUID(),"materialCode","TEST-MOTOR","description","TEST isolated material demand","unit","PCS","quantity",10,"requiredDate",today().plusDays(30).toString(),"leadTimeDays",30,"criticalPath",true,"buyerUserId",user(1).toString());}
 static final HttpClient HTTP=HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).connectTimeout(java.time.Duration.ofSeconds(3)).build();
 static HttpResponse<String> request(int port,int who,String path,Object body,String key) throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(java.time.Duration.ofSeconds(15));if(who>0)b.header("Authorization","Bearer "+token(who));if(body!=null){b.header("Content-Type","application/json");if(key!=null)b.header("Idempotency-Key",key);b.POST(HttpRequest.BodyPublishers.ofString(JSON.writeValueAsString(body)));}return HTTP.send(b.build(),HttpResponse.BodyHandlers.ofString());}
 static String keyId(){return UUID.randomUUID().toString();}
 static Map<String,Object> event(int revision,String code,Map<String,Object> payload){return Map.of("expectedRevision",revision,"eventCode",code,"note","TEST "+code,"payload",payload,"evidenceRefs",List.of("hrx-file:test/recovery"));}
}
